class Solution:
    def constructDistancedSequence(self, n: int) -> list[int]:
        size = 2 * n - 1
        result = [0] * size
        used = [False] * (n + 1)

        def backtrack(idx: int) -> bool:
            if idx == size:
                return True
            if result[idx] != 0:
                return backtrack(idx + 1)
            for num in range(n, 0, -1):
                if used[num]:
                    continue
                if num == 1:
                    result[idx] = 1
                    used[1] = True
                    if backtrack(idx + 1):
                        return True
                    result[idx] = 0
                    used[1] = False
                else:
                    if idx + num < size and result[idx + num] == 0:
                        result[idx] = num
                        result[idx + num] = num
                        used[num] = True
                        if backtrack(idx + 1):
                            return True
                        result[idx] = 0
                        result[idx + num] = 0
                        used[num] = False
            return False

        backtrack(0)
        return result

